try{const saved=localStorage.getItem('careerpilot-ui-locale');if(localeResources[saved])uiLocale=saved;}catch{}
function uiText(key){return localeResources[uiLocale][key]??localeResources['zh-CN'][key]??key;}
function uiFormat(key,values={}){return uiText(key).replace(/\{(\w+)\}/g,(match,name)=>name in values?String(values[name]):match);}
// The language of arbitrary owner text is unknown. Reset inherited UI language;
// never infer a translation or a language from the selected interface locale.
function uiOriginal(value){return `<bdi lang="" dir="auto" data-original-content>${escapeHTML(value??'')}</bdi>`;}
function uiSource(value,language='zh-CN'){return `<span lang="${escapeHTML(language)}" data-source-content>${escapeHTML(value??'')}</span>`;}
function uiLabels(prefix,keys){return Object.defineProperties({},Object.fromEntries(keys.map(key=>[key,{enumerable:true,get:()=>uiText(prefix+'.'+key)}])));}
function uiFixed(original,translated){return uiLocale==='en-US'&&typeof translated==='string'?escapeHTML(translated):uiSource(original);}
function uiMoment(value,zone='Asia/Shanghai'){return value?new Intl.DateTimeFormat(uiLocale,{timeZone:zone,year:'numeric',month:'short',day:'numeric',hour:'2-digit',minute:'2-digit',timeZoneName:'shortOffset'}).format(new Date(value)):uiText('unknown');}
function uiFormFields(container){
  container.querySelectorAll('select,textarea,input:not([type="checkbox"]):not([type="radio"])').forEach(input=>{
    const label=input.closest('label');
    if(label){const copy=label.cloneNode(true);copy.querySelectorAll('select,textarea,input').forEach(node=>node.remove());input.setAttribute('aria-label',copy.textContent.trim());}
    if(input.matches('textarea,input:not([type]),input[type="text"]')){input.lang='';input.dir='auto';input.setAttribute('data-original-content','');}
  });
  container.querySelectorAll('h2,h3,h4').forEach(heading=>heading.tabIndex=-1);
}
function focusLearningResult(container){container.querySelector('h2,h3')?.focus({preventScroll:false});}
function focusGrowthHeading(container){container.querySelector('h3')?.focus({preventScroll:false});}
/* Same-origin API calls carry the interface locale so fixed server explanations match the UI. */
const nativeFetch=window.fetch.bind(window);
window.fetch=(input,init={})=>{
  const url=typeof input==='string'?input:input instanceof URL?input.pathname:input.url;
  if(String(url).startsWith('/api/')||String(url).startsWith(location.origin+'/api/')){
    const headers=new Headers(init.headers||(input instanceof Request?input.headers:undefined));
    if(!headers.has('Accept-Language'))headers.set('Accept-Language',uiLocale);
    init={...init,headers};
  }
  return nativeFetch(input,init);
};
function uiDate(value,zone='Asia/Shanghai'){
  if(!value)return uiLocale==='en-US'?'Unknown':'未知';
  if(/^\d{4}-\d{2}-\d{2}$/.test(value))return new Intl.DateTimeFormat(uiLocale,{timeZone:'UTC',dateStyle:'medium'}).format(new Date(value+'T00:00:00Z'));
  return new Intl.DateTimeFormat(uiLocale,{timeZone:zone,dateStyle:'medium',timeStyle:'short'}).format(new Date(value));
}
// HTML date inputs require ISO calendar dates, independently of display locale.
function uiCalendarDate(value=new Date(),zone='Asia/Shanghai'){
  const parts=new Intl.DateTimeFormat('en-US',{timeZone:zone,year:'numeric',month:'2-digit',day:'2-digit'}).formatToParts(value);
  const part=type=>parts.find(item=>item.type===type).value;
  return `${part('year')}-${part('month')}-${part('day')}`;
}
function localizeNavigation(){
  document.documentElement.lang=uiLocale;
  document.title=uiText('docTitle');
  // Business pages default to their original language; shell-rendered pages override it.
  document.querySelector('#view').lang='zh-CN';
  document.querySelector('#ui-locale').value=uiLocale;
  document.querySelector('#locale-scope').textContent=uiText('preview');
  document.querySelector('.skip').textContent=uiText('skip');
  document.querySelector('#menu').setAttribute('aria-label',uiText('menu'));
  document.querySelector('#connect').textContent=uiText(token?'connected':'connect');
  for(const node of document.querySelectorAll('[data-i18n]'))node.textContent=uiText(node.dataset.i18n);
  for(const node of document.querySelectorAll('[data-i18n-aria]'))node.setAttribute('aria-label',uiText(node.dataset.i18nAria));
  for(const link of document.querySelectorAll('a.local-use-link'))link.setAttribute('href','local-use.html'+(uiLocale==='en-US'?'#english':''));
  for(const link of document.querySelectorAll('nav a[data-page]')){
    const label=link.querySelector('span:last-child');if(label)label.textContent=uiText(link.dataset.page);
  }
  for(const key of ['settings','admin'])document.querySelector('.nav-bottom a[href="#'+key+'"]').textContent=uiText(key);
  for(const id of ['breadcrumb','context'])document.querySelector('#'+id).textContent=uiText(current);
  document.querySelector('#title').textContent=uiText(current==='dashboard'?'home':current);
  document.querySelector('#subtitle').textContent=uiText('sub.'+current);
}
document.addEventListener('change',async event=>{
  if(event.target.id!=='ui-locale')return;
  uiLocale=localeResources[event.target.value]?event.target.value:'zh-CN';
  try{localStorage.setItem('careerpilot-ui-locale',uiLocale);}catch{}
  await render();
});
